const fmt = (value, digits = 2) => value === null || value === undefined || !Number.isFinite(Number(value)) ? 'não identificado' : Number(value).toLocaleString('pt-BR', {minimumFractionDigits: digits, maximumFractionDigits: digits});
const money = (value) => value === null || value === undefined || !Number.isFinite(Number(value)) ? 'não identificado' : Number(value).toLocaleString('pt-BR', {style: 'currency', currency: 'BRL'});
const pct = (value) => `${fmt(value)}%`;
const summary = analysis.summary;
const classification = summary.final_points === null ? 'INDETERMINADA' : summary.final_points >= 100 ? 'ACIMA DO OBJETIVO (posição parcial)' : summary.final_points >= 90 ? 'PARCIAL — próxima do objetivo' : 'PARCIAL — requer recuperação';
const lines = [];
lines.push(`ANÁLISE POBJ — ${analysis.period ?? 'período não identificado'}`);
lines.push(`Classificação: ${classification}`);
lines.push('');
lines.push(`Posição-base: ${analysis.base_date ?? 'não identificada'}. O resultado é uma fotografia dessa data e não confirma movimentos posteriores.`);
lines.push('');
lines.push('SITUAÇÃO GERAL');
lines.push(`• Pontos possíveis: ${fmt(summary.possible_points)}`);
lines.push(`• Pontos projetados: ${fmt(summary.achieved_points)}`);
lines.push(`• Atingimento projetado: ${pct(summary.attainment_percent)}`);
lines.push(`• Aceleradores: ${summary.accelerator_points === null ? 'não identificado' : `${summary.accelerator_points >= 0 ? '+' : ''}${fmt(summary.accelerator_points)}`}`);
lines.push(`• Resultado final projetado: ${pct(summary.final_points)}`);
const strengths = analysis.strengths.slice(0,5);
if (strengths.length) { lines.push(''); lines.push('PONTOS FORTES'); strengths.forEach((item) => lines.push(`• ${item.name}: ${pct(item.attainment_percent)}${item.projected_final_percent !== null ? `; projeção ${pct(item.projected_final_percent)}` : ''}${item.reported_points !== null ? `; ${fmt(item.reported_points)} pts` : ''}.`)); }
const lowerRisks = analysis.indicators.filter((item) => item.weight > 0 && item.goal_direction === 'LOWER_IS_BETTER').sort((a,b) => (b.reported_points ?? 0) - (a.reported_points ?? 0)).slice(0,3);
const priority = analysis.priority_candidates.slice(0,5);
if (lowerRisks.length || priority.length) { lines.push(''); lines.push('RISCOS E GAPS'); lowerRisks.forEach((item) => { let extra = ''; if (/vencidos/i.test(item.name) && item.target !== null && item.achieved !== null && item.attainment_percent !== null && item.attainment_percent < 90) { const gap90 = Math.max(0, item.target * 0.90 - item.achieved); extra = `; faltam aproximadamente ${money(gap90)} para 90% usando os valores da fonte`; } lines.push(`• ${item.name}: ${pct(item.attainment_percent)}${item.reported_points !== null ? `; ${fmt(item.reported_points)} pts` : ''}${extra}.`); }); priority.forEach((item) => lines.push(`• ${item.name}: ${pct(item.attainment_percent)}${item.daily_need !== null ? `; necessidade diária informada ${fmt(item.daily_need)}` : ''}.`)); }
const validatedById = new Map((analysis.general_rule_validation?.validations ?? []).filter((item) => item.status === 'MATCH').map((item) => [item.indicator_id, item]));
const scenarios = priority.filter((item) => validatedById.has(item.indicator_id) && item.reported_points !== null).map((item) => ({name: item.name, current: item.reported_points, target: item.weight, gain: Math.max(0, item.weight - item.reported_points)})).filter((item) => item.gain > 0.005).slice(0,3);
if (scenarios.length) { lines.push(''); lines.push('CENÁRIOS CONFERÍVEIS'); lines.push(`• Base reportada: ${pct(summary.final_points)}.`); scenarios.forEach((item) => lines.push(`• Se ${item.name} alcançar 100% pela regra ativa: ganho estimado de até ${fmt(item.gain)} pts (de ${fmt(item.current)} para ${fmt(item.target)}).`)); const combined = scenarios.reduce((sum,item) => sum + item.gain, 0); if (summary.final_points !== null) lines.push(`• Potencial combinado desses cenários: aproximadamente ${pct(summary.final_points + combined)}. Não inclui mudanças em outros indicadores.`); }
lines.push('');
lines.push('CAMINHO RECOMENDADO');
const actions = analysis.recommended_actions.slice(0,4);
if (actions.length) actions.forEach((item,index) => lines.push(`${index + 1}. ${item.action}`)); else lines.push('1. Preservar os indicadores já conquistados e revisar os campos sem regra homologada.');
const first = priority[0] ?? lowerRisks[0] ?? strengths[0];
lines.push('');
lines.push(`PRÓXIMA AÇÃO: ${first ? `revisar ${first.name} e confirmar a produção ainda não refletida após ${analysis.base_date ?? 'a data-base'}` : 'confirmar a atualização do relatório e os indicadores materiais'}.`);
lines.push(`POR QUÊ: ${first ? 'é o primeiro ponto material identificado pelo ranking governado do GG Performance' : 'o arquivo não trouxe candidato suficiente para priorização automática'}.`);
lines.push('RISCO DE NÃO AGIR: perder pontuação projetada ou tomar decisão com uma posição desatualizada.');
lines.push(`CONFIANÇA: ${analysis.decision_status === 'READY' ? 'alta nos valores reportados e nas regras validadas; média nos cenários até o fechamento definitivo' : 'média; existem campos ou regras que exigem revisão'}.`);
if (analysis.data_gaps.length) { lines.push(''); lines.push(`OBSERVAÇÕES: ${analysis.data_gaps.length} lacuna(s) preservada(s); nenhum valor ausente foi inventado.`); }
let richSummary = lines.join('\n');
if (richSummary.length > 3900) richSummary = `${richSummary.slice(0,3820)}\n\n[Resumo limitado pelo Telegram; detalhes completos permanecem no Estado 360.]`;
const executive_assessment = {...envelope.executive_assessment, summary: richSummary, classification, sections: {strengths: strengths.length, risks: lowerRisks.length + priority.length, scenarios: scenarios.length, actions: actions.length}, producer_version: '1.1.0'};
const completion = envelope.completion_payload;
completion.result.executive_assessment = executive_assessment;
return [{json: {...envelope, executive_assessment, completion_payload: completion}}];

const { randomUUID } = require('crypto');
const envelope = $input.first().json;
if (envelope?.valid !== true || envelope?.result?.ok !== true) throw new Error('VALID_EXTRACTION_REQUIRED');
const extraction = envelope.result.extraction ?? {};
const tables = Array.isArray(extraction.tables) ? extraction.tables : [];
const markdown = String(extraction.markdown ?? extraction.text ?? '');
const structuredText = tables.map((table) => [table.headers, ...(table.rows ?? [])].flat().join(' ')).join(' ');
const text = `${markdown} ${structuredText}`.trim();
const normalized = `${extraction.file_name ?? ''} ${text}`.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const signals = ['pobj','meta','realizado','atingimento','pontuacao','pontos','consorcio','seguros','captacao','credito pj','open finance'];
const matched = signals.filter((term) => normalized.includes(term));
const fileHint = /pobj|meta|objetivo|performance/.test(String(extraction.file_name ?? '').toLowerCase());
const isPerformance = matched.length >= 2 || (fileHint && matched.length >= 1);
const decisionStatus = isPerformance ? 'READY' : 'MANUAL_REVIEW_REQUIRED';
const routing = {
  schema_version: '1.0.0',
  routing_id: randomUUID(),
  routing_method: 'DETERMINISTIC',
  rule_id: 'mvp.performance.document-signals.v1',
  intent: isPerformance ? 'ANALISAR_METAS_POBJ' : 'CLASSIFICACAO_DOCUMENTAL_INCONCLUSIVA',
  selected_domains: isPerformance ? [{
    domain: 'performance',
    requirement: 'REQUIRED',
    capabilities: ['PERFORMANCE_SOURCES_RECONCILIATION','PERFORMANCE_SCORING_STATE','PERFORMANCE_GAP_SCENARIOS']
  }] : [],
  excluded_domains: ['conta','financeiro','relacionamento'].map((domain) => ({domain, reason_code: 'NOT_REQUIRED_FOR_INTENT'})),
  dependencies: isPerformance ? [{before: 'DOCUMENT_EXTRACTION_VALIDATED', after: 'PERFORMANCE_SOURCES_RECONCILIATION'}] : [],
  fallback: 'MANUAL_REVIEW_REQUIRED',
  decision_status: decisionStatus
};
const minimalEvidence = (extraction.evidence ?? []).slice(0, 80).map(({locator,text,extraction_method,confidence}) => ({locator,text:String(text ?? '').slice(0,8000),extraction_method,confidence:confidence ?? null}));
const performanceHandoff = isPerformance ? {
  schema_version: '1.0.0',
  handoff_id: randomUUID(),
  handoff_target: 'GERENTE_GERAL_PERFORMANCE',
  job_id: envelope.job_id,
  source: {
    file_name: extraction.file_name,
    mime_type: extraction.mime_type,
    content_hash: extraction.content_hash,
    extraction_method: extraction.extraction_method,
    page_count: extraction.page_count ?? null,
    parser: extraction.parser ?? null
  },
  intent: routing.intent,
  matched_signals: matched,
  extracted_text: text.slice(0,200000),
  markdown: markdown.slice(0,200000),
  tables: tables.slice(0,100),
  sections: (extraction.sections ?? []).slice(0,500),
  extraction_warnings: extraction.warnings ?? [],
  evidence: minimalEvidence,
  capabilities: routing.selected_domains[0].capabilities,
  data_gaps: [],
  security: {content_trust: 'UNTRUSTED', external_effects_allowed: false}
} : null;
return [{json: {...envelope, routing, performance_handoff: performanceHandoff, orchestration: {director: 'DIRETOR_360_MVP', version: '1.0.0', matched_signals: matched, confidence: isPerformance ? (matched.length >= 4 ? 'HIGH' : 'MEDIUM') : 'LOW'}}}];

