const senderIsBot = Boolean((update.callback_query?.from ?? message.from)?.is_bot);
const eventKind = update.callback_query ? 'CALLBACK' : message.document ? 'DOCUMENT' : Array.isArray(message.photo) && message.photo.length ? 'IMAGE' : text.startsWith('/') ? 'COMMAND' : text ? 'TEXT' : 'OTHER';
const canonical = JSON.stringify(update);
const transportSecret = String(headers['x-director360-transport'] ?? headers['X-Director360-Transport'] ?? '');
return [{ json: {
  channel: 'TELEGRAM', tenant_id: 'rafael-360', owner_id: 'rafael',
  external_update_id: updateId, chat_id: chatId, message_id: String(message.message_id ?? ''),
  sender_is_bot: senderIsBot, event_kind: eventKind, text_content: text,
